+    memset(dst, 0, dst_len);
+
+    /* Process digits from end of string to start, same as bcd_buf_from_u32
+     * processes val from least to most significant digit.
+     * This produces identical BCD layout: least significant byte-pair first. */
+    for (int i = len - 1; i >= 0; i--) {
+        if (!_is_digit(str[i])) {
+            continue;
+        }
+
+        hex <<= 4;
+        hex += str[i] - '0';
