+        if (++idx % 2 == 0) {
+            if (digit_count + 1 > dst_len) {
+                return -ENOBUFS;
+            }
+            *tgt++ = swap_nibbles(hex);
+            hex = 0;
+            digit_count++;
+        }
+    }
+
+    if (idx % 2) {
+        if (digit_count + 1 > dst_len) {
+            return -ENOBUFS;
+        }
+        *tgt++ = hex;
+        digit_count++;
+    }
+
+    return digit_count;
 }

