+     * From https://tools.ietf.org/html/rfc5915#section-3
+     *
+     * ECPrivateKey ::= SEQUENCE {
+     *      version        INTEGER { ecPrivkeyVer1(1) } (ecPrivkeyVer1),
+     *      privateKey     OCTET STRING,
+     *      parameters [0] ECParameters OPTIONAL,
+     *      publicKey  [1] BIT STRING OPTIONAL
+     * }
+     */
+
+    /* the outer container should be a SEQUENCE */
+    if (ecc_key.type != ASN1_TYPE_SEQUENCE) {
+        DEBUG("credman: the private ECC key should be contained in an ASN.1 SEQUENCE\n");
+        return CREDMAN_INVALID;
+    }
+
+    asn1_tree *node = ecc_key.child;
+
+    /* check version */
+    if (!node || node->type != ASN1_TYPE_INTEGER) {
+        DEBUG("credman: invalid private ECC key version\n");
+        return CREDMAN_INVALID;
+    }
+
+    /* point to privateKey */
+    node = node->next;
+    if (!node || node->type != ASN1_TYPE_OCTET_STRING || !node->data || !node->length) {
+        DEBUG("credman: no private key found\n");
+        return CREDMAN_INVALID;
+    }
+
+    cred->params.ecdsa.private_key = node->data;
+
+    /* look for optional publicKey [1] */
+    node = node->next;
+    while (node) {
+        if (node->type == ASN1_CONTEXT_TAG(1)) {
+            if (_parse_ecc_point(node->child, &cred->params.ecdsa.public_key.x,
+                                 &cred->params.ecdsa.public_key.y) != CREDMAN_OK) {
+                DEBUG("credman: could not parse public key from private ECC key\n");
+                return CREDMAN_INVALID;
+            }
+            break;
+        }
+        node = node->next;
+    }
+
+    return CREDMAN_OK;
