+                params[idx].name_len = eq - query;
+                params[idx].value = eq + 1;
+                params[idx].value_len = segment_end - (eq + 1);
+            }
+            else {
+                params[idx].name = query;
+                params[idx].name_len = segment_end - query;
+                params[idx].value = NULL;
+                params[idx].value_len = 0;
